const stripArabicBidiControls=(value)=>String(value??"")
  .replace(/[\u202A-\u202E\u2066-\u2069]/g,"")
  .replace(/\s+/g," ")
  .trim();

PRODUCTS_DATA.forEach((product)=>{
  product.nameAr=stripArabicBidiControls(AR_PRODUCT_NAME_FIXES[product.id]||product.nameAr||"");
  if(Array.isArray(product.variants)){
    product.variants.forEach((variant)=>{
      if(variant.sizeAr!=null)variant.sizeAr=stripArabicBidiControls(variant.sizeAr);
    });
  }
});

